import unittest
from candidate import string_sequence

class TestStringSequence(unittest.TestCase):
    def test_zero_input_returns_single_zero(self):
        self.assertEqual(string_sequence(0), "0")

    def test_positive_input_returns_correct_sequence(self):
        self.assertEqual(string_sequence(5), "0 1 2 3 4 5")

    def test_single_number_input_returns_two_numbers(self):
        self.assertEqual(string_sequence(1), "0 1")

    def test_large_input_returns_correct_length(self):
        result = string_sequence(10)
        numbers = result.split()
        self.assertEqual(len(numbers), 11)
        self.assertEqual(numbers[0], "0")
        self.assertEqual(numbers[-1], "10")

    def test_negative_input_returns_empty_string(self):
        self.assertEqual(string_sequence(-1), "")
        self.assertEqual(string_sequence(-5), "")

    def test_output_is_string_type(self):
        self.assertIsInstance(string_sequence(3), str)

    def test_output_has_no_trailing_space(self):
        self.assertFalse(string_sequence(3).endswith(" "))

    def test_output_has_no_leading_space(self):
        self.assertFalse(string_sequence(3).startswith(" "))

    def test_input_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_sequence(None)

    def test_input_float_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_sequence(2.5)

    def test_input_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_sequence("5")

    def test_input_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_sequence([1, 2, 3])

    def test_input_dict_raises_type_error(self):
        with self.assertRaises(TypeError):
            string_sequence({"a": 1})

    def test_sequence_contains_all_numbers(self):
        seq = string_sequence(7)
        numbers = seq.split()
        expected = [str(i) for i in range(8)]
        self.assertEqual(numbers, expected)

    def test_sequence_contains_only_numbers_and_spaces(self):
        seq = string_sequence(4)
        for char in seq:
            self.assertTrue(char.isdigit() or char.isspace())

    def test_sequence_for_zero_and_negative_combinations(self):
        self.assertEqual(string_sequence(0), "0")
        self.assertEqual(string_sequence(-2), "")

    def test_sequence_with_large_n(self):
        n = 1000
        seq = string_sequence(n)
        numbers = seq.split()
        self.assertEqual(len(numbers), n + 1)
        self.assertEqual(numbers[0], "0")
        self.assertEqual(numbers[-1], str(n))

    def test_sequence_not_modified_by_external_change(self):
        original = string_sequence(3)
        _ = original.split()
        self.assertEqual(string_sequence(3), "0 1 2 3")

    def test_sequence_return_value_is_not_cached(self):
        first = string_sequence(2)
        second = string_sequence(2)
        self.assertEqual(first, second)
        self.assertIsNot(first, second)

    def test_sequence_does_not_include_negative_numbers(self):
        seq = string_sequence(5)
        self.assertNotIn("-1", seq)
        self.assertNotIn("-2", seq)

if __name__ == "__main__":
    unittest.main()
